from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
marker='simpla-mobile-switches-global-v7'
if marker in s:
    raise SystemExit('patch já aplicado')
css=r'''\n<style id="simpla-mobile-switches-global-v7">\n@media (max-width:768px){\n  #configuracoes label.simpla-switch-row-v7{\n    display:grid!important;\n    grid-template-columns:44px minmax(0,1fr)!important;\n    column-gap:12px!important;\n    align-items:center!important;\n    width:100%!important;\n    min-width:0!important;\n    margin:8px 0!important;\n    padding:0!important;\n    font-size:11.5px!important;\n    line-height:1.28!important;\n    white-space:normal!important;\n  }\n  #configuracoes label.simpla-switch-row-v7 > input[type="checkbox"]{\n    grid-column:1!important;\n    position:static!important;\n    left:auto!important;right:auto!important;top:auto!important;bottom:auto!important;\n    transform:none!important;\n    margin:0!important;\n    width:42px!important;min-width:42px!important;max-width:42px!important;\n    justify-self:start!important;\n  }\n  #configuracoes label.simpla-switch-row-v7 > .simpla-switch-text-v7{\n    grid-column:2!important;\n    min-width:0!important;\n    display:block!important;\n    margin:0!important;\n    padding:0!important;\n    font-size:11.5px!important;\n    line-height:1.28!important;\n    overflow-wrap:anywhere!important;\n    word-break:normal!important;\n  }\n  #configuracoes .profissional-servico-item{\n    display:grid!important;\n    grid-template-columns:44px minmax(0,1fr) 84px!important;\n    column-gap:12px!important;\n    align-items:center!important;\n  }\n  #configuracoes .profissional-servico-item > input[type="checkbox"]{\n    position:static!important;transform:none!important;margin:0!important;\n    width:42px!important;min-width:42px!important;max-width:42px!important;\n    grid-column:1!important;\n  }\n  #configuracoes .profissional-servico-item > span{\n    grid-column:2!important;min-width:0!important;margin:0!important;padding:0!important;\n  }\n  #configuracoes .profissional-servico-item > input[type="number"]{\n    grid-column:3!important;width:84px!important;min-width:84px!important;max-width:84px!important;\n  }\n}\n@media (max-width:420px){\n  #configuracoes label.simpla-switch-row-v7{\n    grid-template-columns:42px minmax(0,1fr)!important;\n    column-gap:10px!important;\n    font-size:11px!important;\n  }\n  #configuracoes label.simpla-switch-row-v7 > .simpla-switch-text-v7{font-size:11px!important;}\n  #configuracoes .profissional-servico-item{\n    grid-template-columns:42px minmax(0,1fr) 80px!important;\n    column-gap:10px!important;\n  }\n  #configuracoes .profissional-servico-item > input[type="number"]{\n    width:80px!important;min-width:80px!important;max-width:80px!important;\n  }\n}\n</style>\n<script id="simpla-mobile-switches-global-v7">\n(function(){\n  function normalizar(){\n    const raiz=document.getElementById('configuracoes');\n    if(!raiz) return;\n    raiz.querySelectorAll('.profissional-servico-item').forEach(el=>{\n      el.classList.remove('simpla-mobile-switch-row','simpla-switch-row-v7');\n    });\n    raiz.querySelectorAll('label').forEach(label=>{\n      const cb=Array.from(label.children).find(el=>el.tagName==='INPUT' && el.type==='checkbox');\n      if(!cb || cb.parentElement!==label) return;\n      if(label.classList.contains('profissional-servico-item')) return;\n      if(label.classList.contains('cfg-switch')) return;\n      if(label.querySelector('.cfg-switch-track')) return;\n      label.classList.add('simpla-switch-row-v7');\n      let wrap=label.querySelector(':scope > .simpla-switch-text-v7');\n      if(!wrap){\n        wrap=document.createElement('span');\n        wrap.className='simpla-switch-text-v7';\n        const mover=Array.from(label.childNodes).filter(n=>n!==cb);\n        mover.forEach(n=>wrap.appendChild(n));\n        label.appendChild(wrap);\n      }\n    });\n  }\n  const iniciar=()=>{\n    normalizar();\n    const raiz=document.getElementById('configuracoes');\n    if(raiz){\n      const obs=new MutationObserver(()=>normalizar());\n      obs.observe(raiz,{childList:true,subtree:true});\n    }\n  };\n  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',iniciar);\n  else iniciar();\n})();\n</script>\n'''
s=s.replace('</head>',css+'\n</head>',1)
p.write_text(s,encoding='utf-8')
